-- ================================================================
-- Legacy ERP Master Data Export (simulated SQL source system)
-- ABC Logistics Ltd. -- customers, warehouses, vehicles, suppliers, products
-- ================================================================

DROP TABLE IF EXISTS erp_customers;
CREATE TABLE erp_customers (
    customer_id TEXT,
    customer_name TEXT,
    email TEXT,
    phone TEXT,
    city TEXT,
    state TEXT,
    country TEXT,
    region TEXT,
    customer_since TEXT,
    customer_type TEXT
);


DROP TABLE IF EXISTS erp_warehouses;
CREATE TABLE erp_warehouses (
    warehouse_id TEXT,
    warehouse_name TEXT,
    city TEXT,
    state TEXT,
    country TEXT,
    region TEXT,
    latitude TEXT,
    longitude TEXT,
    capacity_sqft TEXT,
    manager_name TEXT,
    operational_since TEXT
);


DROP TABLE IF EXISTS erp_vehicles;
CREATE TABLE erp_vehicles (
    vehicle_id TEXT,
    vehicle_type TEXT,
    registration_number TEXT,
    fuel_type TEXT,
    capacity_kg TEXT,
    manufacture_year TEXT,
    home_warehouse_id TEXT,
    driver_name TEXT,
    driver_license_no TEXT,
    status TEXT
);


DROP TABLE IF EXISTS erp_suppliers;
CREATE TABLE erp_suppliers (
    supplier_id TEXT,
    supplier_name TEXT,
    contact_person TEXT,
    email TEXT,
    phone TEXT,
    city TEXT,
    country TEXT,
    category TEXT,
    onboarded_date TEXT,
    rating TEXT
);


DROP TABLE IF EXISTS erp_products;
CREATE TABLE erp_products (
    product_id TEXT,
    product_name TEXT,
    category TEXT,
    unit_weight_kg TEXT,
    unit_price TEXT,
    supplier_id TEXT
);
